<script lang="ts">import { navigate } from 'svelte-routing'; import { getOrder, getProducts } from '../data/store'; import type { Order, Product } from '../types'; let { id }: { id: string } = $props(); let order = $state<Order>(); let products = $state<Product[]>([]); $effect(() => { getOrder(id).then((value) => order = value); getProducts().then((value) => products = value) })</script>
{#if order}<section class="mx-auto max-w-4xl"><button onclick={() => history.back()} class="text-sm font-semibold text-primary">← Back to orders</button><div class="mt-5 rounded-panel bg-card p-6 ring-1 ring-line"><div class="flex flex-col justify-between gap-3 sm:flex-row"><div><p class="text-sm font-semibold text-success">Order confirmed</p><h1 class="mt-1 text-3xl font-bold text-navy">{order.id}</h1><p class="mt-2 text-muted">Placed {new Date(order.createdAt).toLocaleDateString()}</p></div><div class="rounded-xl bg-green-50 px-4 py-3 text-sm font-semibold text-success">{order.status} · {order.paymentStatus}</div></div><h2 class="mt-8 border-b border-line pb-3 text-lg font-bold text-navy">Items</h2>{#each order.items as item (item.productId + item.color)}<div class="flex justify-between py-4"><div><p class="font-semibold text-navy">{products.find((product) => product.id === item.productId)?.name ?? 'Product'}</p><p class="text-sm text-muted">{item.color} · Quantity {item.quantity}</p></div><p class="font-semibold text-navy">${((products.find((product) => product.id === item.productId)?.price ?? 0) * item.quantity).toFixed(2)}</p></div>{/each}<div class="mt-3 flex justify-between border-t border-line pt-4 text-lg font-bold text-navy"><span>Total paid</span><span>${order.total.toFixed(2)}</span></div><div class="mt-8 rounded-xl bg-surface p-4"><p class="font-semibold text-navy">Delivering to {order.address.label}</p><p class="mt-1 text-sm text-muted">{order.address.recipient}, {order.address.line1}, {order.address.city}, {order.address.state} {order.address.postalCode}</p></div></div></section>{:else}<section class="p-8 text-center"><h1 class="text-xl font-bold text-navy">Order not found</h1><button onclick={() => navigate('/orders')} class="mt-4 text-primary">View all orders</button></section>{/if}
